package me.pikanote.companion;
import android.app.*;import android.content.*;import org.json.*;import java.io.*;
final class ArchiveConflictChecks{
 static void run(Instrumentation i)throws Exception{Context real=i.getTargetContext();File dir=new File(real.getFilesDir(),"archive-conflict-check");Context box=new ContextWrapper(real){public File getFilesDir(){dir.mkdirs();return dir;}};Store store=new Store(box);try{
 JSONObject create=new JSONObject().put("kind","memories").put("action","save").put("record",new JSONObject().put("text","Fixture memory").put("date","2026-10-29T12:00"));String local=store.api("/api/manager","POST",create.toString()).json().getString("id");store.api("/api/manager","POST",new JSONObject().put("kind","memories").put("action","delete").put("id",local).toString());JSONObject pending=store.state.getJSONArray("pending").getJSONObject(1),remote=new JSONObject("{\"memories\":[],\"tasks\":[],\"events\":[]}");JSONObject row=new JSONObject(pending.getJSONObject("base").toString()).put("id","m500").put("archived",false);remote.getJSONArray("memories").put(row);store.state.getJSONObject("ids").put(local,"m500");store.checkBase(remote,pending);row.put("archived",true);boolean conflict=false;try{store.checkBase(remote,pending);}catch(IOException expected){conflict=true;}if(!conflict)throw new Exception("Real archive conflict was ignored");row.put("archived",false).put("text","Different device edit");conflict=false;try{store.checkBase(remote,pending);}catch(IOException expected){conflict=true;}if(!conflict)throw new Exception("Real text conflict was ignored");for(String key:new String[]{"archived","done","allDay"}){if(!Store.sameRecordField(new JSONObject(),new JSONObject().put(key,false),key))throw new Exception("Missing false flag mismatch");if(Store.sameRecordField(new JSONObject(),new JSONObject().put(key,true),key))throw new Exception("True flag ignored");}
 }finally{PhoneBackup.remove(dir);}}
}
